let compute_shader = """
#version 330 core

layout (local_size_x = 16, local_size_y = 1, local_size_z = 1) in;

layout (std430, binding = 0) buffer BufferObject
{
    float arr[256];
};

void main()
{
    uint gid = gl_GlobalInvocationID.x;
    arr[gid] = arr[gid] * arr[gid];
}
"""

let () =
  Core.init ();
  Glfw.init ~init:`JOYSTICKS;
  Glfw.window_hint ~hint:`CONTEXT_VERSION_MAJOR 3;
  Glfw.window_hint ~hint:`CONTEXT_VERSION_MINOR 3;
  Glfw.window_hint ~hint:`OPENGL_PROFILE `CORE;
  Glfw.window_hint ~hint:`OPENGL_FORWARD_COMPAT true;

  let window = Glfw.create_window ~width:800 ~height:600 "Compute Shader Example" ~monitor:`NONE ~opengl:(`TRUE) in

  Glfw.make_context_current window;
  Opengl.load_functions ();

  let program =
    Gl.create_program ()
    |> Gl.attach_shader ~shader:`VERTEX_SHADER (Gl.create_shader ~shader:`VERTEX_SHADER (vertex_shader |> Gl.create_shader))
    |> Gl.attach_shader ~shader:`COMPUTE_SHADER (Gl.create_shader ~shader:`COMPUTE_SHADER (compute_shader |> Gl.create_shader))
    |> Gl.link_program
  in

  let buffer = Gl.create_buffer () in
  Gl.named_buffer_data
    ~size:(256 * 4)
    ~usage:(Gl.DYNAMIC_DRAW | Gl.MAP_WRITE_BIT)
    ~data:`FLOAT (Array.init 256 (fun _ -> 1.0))
    buffer;

  Gl.use_program program;
  Gl.bind_buffer ~target:`UNIFORM_BUFFER ~buffer:(Gl.create_buffer ()) 0;
  Gl.dispatch_compute 256 1 1;
  Gl.memory_barrier ~target:`BUFFER_UPDATE_BARRIER;
  Gl.bind_buffer ~target:`UNIFORM_BUFFER ~buffer:(Gl.create_buffer ()) 0;
  Gl.dispatch_compute 256 1 1;
  Gl.memory_barrier ~target:`BUFFER_UPDATE_BARRIER;

