extern "C" JNIEXPORT void JNICALL
Java_ReverbEffect_addReverb(JNIEnv *env, jobject thiz, jbyteArray audioData, jint offset, jint length) {
    jbyte *data = env->GetByteArrayElements(audioData, NULL);

    // Get the audio data from the Java Sound API
    JavaSoundBuffer buffer = inputDataSource.read();
    short *audioBuffer = buffer.getData();

    // Apply reverb effect
    for (int i = 0; i < length / 2; i++) {
        // Example reverb effect
        audioBuffer[i] = (short) (data[i + offset] * 1.5f);
    }

    // Write the audio data back to the Java Sound API
    inputDataSource.write(buffer);

    env->ReleaseByteArrayElements(audioData, data, 0);
}

extern "C" JNIEXPORT jint JNICALL
Java_ReverbEffect_startRecording(JNIEnv *env, jobject thiz) {
    // Initialize the Java Sound API
    InputStream inputStream = AudioSystem.getAudioInputStream(Microphone.getBestMicrophone());
    AudioFormat format = inputStream.getFormat();
    inputDataSource.open(inputStream);

    // Initialize PortAudio
    PaError err = Pa_Initialize();
    if (err != paNoError) return err;

    // Set up the PortAudio stream
    PaStreamParameters outParams;
    outParams.device = Pa_GetDefaultOutputDevice();
    if (outParams.device == paNoDevice) {
        Pa_Terminate();
        return -1;
    }
    outParams.channelCount = format.getChannels();
    outParams.sampleFormat = paInt16;
    outParams.suggestedLatency = Pa_GetDeviceInfo(outParams.device)->defaultLowOutputLatency;
    err = Pa_OpenStream(&stream, NULL, &outParams, format.getSampleRate(), paFramesPerBufferUnspecified,
                       paClipOff, NULL, NULL);
    if (err != paNoError) {
        Pa_Terminate();
        return err;
    }

    // Start recording
    err = Pa_StartStream(stream);
    if (err != paNoError) {
        Pa_Terminate();
        return err;
    }

    return 0;
}

extern "C" JNIEXPORT jint JNICALL
Java_ReverbEffect_stopRecording(JNIEnv *env, jobject thiz) {
    Pa_StopStream(stream);
    Pa_CloseStream(stream);
    Pa_Terminate();
    inputDataSource.close();
    return 0;
}
