 Here is a simple implementation of a sprite editor using JavaScript and HTML5 canvas:

```html
<!DOCTYPE html>
<html>
<body>
<canvas id="canvas" width="500" height="500"></canvas>
<br>
<button onclick="saveSprite()">Save Sprite</button>

<script>
class SpriteEditor {
  constructor(canvas) {
    this.canvas = canvas;
    this.context = canvas.getContext('2d');
    this.image = new Image();
    this.image.src = "path/to/your/sprite.png";
    this.image.onload = () => {
      this.spriteWidth = this.image.width / 5;
      this.spriteHeight = this.image.height;
      this.currentFrame = 0;
      this.drawSprite();
    };
    this.canvas.addEventListener('mousedown', (e) => {
      this.onMouseDown(e);
    });
  }

  drawSprite() {
    this.context.clearRect(0, 0, this.canvas.width, this.canvas.height);
    this.context.drawImage(
      this.image,
      this.currentFrame * this.spriteWidth,
      0,
      this.spriteWidth,
      this.spriteHeight,
      0,
      0,
      this.spriteWidth,
      this.spriteHeight
    );
  }

  onMouseDown(e) {
    const rect = this.canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    if (x >= 0 && x < this.spriteWidth && y >= 0 && y < this.spriteHeight) {
      this.currentFrame++;
      if (this.currentFrame >= this.image.width / this.spriteWidth) {
        this.currentFrame = 0;
      }
      this.drawSprite();
    }
  }

  saveSprite() {
    const image = new Image();
    image.src = this.canvas.toDataURL('image/png');
    document.body.appendChild(image);
  }
}

const canvas = document.getElementById('canvas');
new SpriteEditor(canvas);
</script>

</body>
</html>
```

