 In Jetpack Compose, you can create a custom composable that changes the content and position of its children based on the available space by using Layout and MeasureScope APIs. However, Compose doesn't have a direct equivalent to container queries in the web. Instead, you can use Compose's intrinsic measurements to achieve similar behavior.

Here's an example of how you could create a custom composable that adjusts its children layout based on available space:

```kotlin
import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.height
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.layout.width
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.layout.Layout
import androidx.compose.ui.tooling.preview.Preview
import androidx.compose.ui.unit.dp

@Composable
fun FlexibleContainer(
    content: @Composable () -> Unit,
    modifier: Modifier = Modifier,
    flexibleSpace: @Composable (Float) -> Unit,
) {
    Layout(
        content = {
            Box(
                modifier = modifier
                    .fillMaxSize()
            ) {
                content()
                flexibleSpace(1f - constraints.maxWidth / constraints.maxHeight)
            }
        },
        modifier = modifier,
    ) { measurables, constraints ->
        val placeableContent = measurables[0].measure(constraints)
        val placeableFlexibleSpace = measurables[1].measure(constraints)

        // Calculate the available space
        val availableWidth = constraints.maxWidth - placeableContent.width
        val availableHeight = constraints.maxHeight - placeableContent.height

        // Position the content and flexible space
        val contentWidth = (availableWidth * (1f - constraints.maxWidth / constraints.maxHeight)).coerceAtLeast(0f)
        val contentHeight = availableHeight.coerceAtLeast(0f)
        val flexibleSpaceWidth = availableWidth.coerceAtMost(0f)
        val flexibleSpaceHeight = availableHeight.coerceAtMost(0f)

        place(
            x = 0,
            y = 0
        ) {
            placeableContent.placeRelative(
                x = (constraints.maxWidth - contentWidth) / 2,
                y = (constraints.maxHeight - contentHeight) / 2
            )
            placeableFlexibleSpace.placeRelative(
                x = (constraints.maxWidth - flexibleSpaceWidth) / 2,
                y = (constraints.maxHeight - flexibleSpaceHeight) / 2
            )
        }
    }
}

